import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {placePanels,waistbandTethers} from '../gui/webgpu/strain.js';

// Real CPU drafts are generated by benchmarks/prepare_trousers.py. They cover
// shorts, wider legs, a synthetic larger body and mixed shirt/trouser outfits.
for(const name of ['default','wide','shorts','custom','outfit'])test(`trousers ${name}: placement keeps each hem around its own leg`,()=>{
 const scene=JSON.parse(readFileSync(new URL(`../output/webgpu/trousers-${name}.json`,import.meta.url)));
 const original=JSON.stringify(scene),result=placePanels(scene);
 assert.equal(JSON.stringify(scene),original,'placement must not alter sewing or material rest lengths');
 assert.equal(result.support.length,0,'trousers must remain free to drape');
 assert.equal(result.adjustments.filter(a=>a.part==='trouser legs').length,1);
 for(const side of ['l','r'])for(const face of ['f','b']){
  const ids=scene.vertex_panels.flatMap((p,i)=>p.endsWith(`pant_${face}_${side}`)?[i]:[]);
  const bottom=Math.min(...ids.map(i=>scene.vertices[i][1]));
  const hem=ids.filter(i=>scene.vertices[i][1]<bottom+.005);
  assert.ok(hem.length>5);
  assert.ok(hem.every(i=>result.positions[i].every(Number.isFinite)));
  assert.ok(hem.every(i=>result.positions[i][0]*(side==='l'?1:-1)>0),'hem crosses to the other leg');
  const z=hem.map(i=>result.positions[i][2]);
  assert.ok(Math.max(...z)-Math.min(...z)>.03,'hem must wrap in depth instead of staying a flat sheet');
 }
 const colors=waistbandTethers(scene);
 assert.ok(colors.flat().length>100);
 for(const color of colors){
  const ids=color.flatMap(c=>c.slice(0,2));assert.equal(new Set(ids).size,ids.length,'GPU batch has shared writes');
  for(const c of color){
   assert.equal(scene.vertex_panels[c[0]],scene.vertex_panels[c[1]],'tether crosses a panel boundary');
   assert.ok(Math.hypot(c[3],c[4])>.035);
  }
 }
});
